import { useState, useCallback } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

export function OnboardingScreen(): JSX.Element {
  const [name, setName] = useState('');
  const [notifications, setNotifications] = useState(false);

  const handleFinish = useCallback(() => {
    // Onboarding complete — hand off to the app shell.
  }, []);

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView
        style={styles.container}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <Text style={styles.heading} accessibilityRole="header">
          Let's get started
        </Text>
        <TextInput
          style={styles.input}
          value={name}
          onChangeText={setName}
          placeholder="Your name"
          accessibilityLabel="Your name"
          accessibilityHint="Enter the name you want us to use"
        />
        <TouchableOpacity
          style={styles.checkbox}
          onPress={() => setNotifications(prev => !prev)}
          accessibilityRole="checkbox"
          accessibilityState={{ checked: notifications }}
          accessibilityLabel="Allow notifications"
        >
          <Text style={styles.checkboxLabel}>Allow notifications</Text>
          <Text style={styles.checkboxMark}>{notifications ? '✓' : ''}</Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={styles.button}
          onPress={handleFinish}
          accessibilityRole="button"
          accessibilityLabel="Finish onboarding"
          accessibilityHint="Completes setup and opens the app"
        >
          <Text style={styles.buttonText}>Finish</Text>
        </TouchableOpacity>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  container: { flex: 1, justifyContent: 'center', padding: 24, gap: 20 },
  heading: { fontSize: 24, fontWeight: '700' },
  input: { borderWidth: 1, borderColor: '#C7C7CC', borderRadius: 8, padding: 12 },
  checkbox: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  checkboxLabel: { fontSize: 16 },
  checkboxMark: { fontSize: 18, fontWeight: '700', color: '#007AFF' },
  button: { backgroundColor: '#007AFF', padding: 14, borderRadius: 8, alignItems: 'center' },
  buttonText: { color: '#fff', fontWeight: '600' },
});
